INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 4, 'theory', 'Quiz: processes and signals');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 0, 'What exactly does fork copy thanks to copy-on-write?', '["The page tables; the pages themselves are copied only on the first write", "All of the process''s memory at once", "Only the CPU registers", "Nothing: the parent and child share memory forever"]', 0, 'Both tables point to the same frames, marked read-only. A write causes a page fault, and the kernel copies one page.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 1, 'How does a thread differ from a process in Linux?', '["A thread runs only in the kernel", "A thread has no stack of its own", "A thread is a task that shares memory and other resources with its neighbors; it is created by the same clone", "Threads cannot be scheduled on different cores"]', 2, 'The kernel works with tasks. The clone flags define what is shared: with no sharing you get a process, with shared memory a thread.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 2, 'What is a zombie process?', '["A process in an eternal D sleep", "A finished process whose exit code the parent has not yet collected with wait", "A process stopped by the STOP signal", "A process without a parent"]', 1, 'All that remains of a zombie is an entry in the process table. You cannot kill it; what helps is terminating or fixing the parent.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 3, 'Who adopts a process whose parent has exited?', '["It terminates immediately", "The grandparent process and only it", "The shell it was started from", "The nearest subreaper or process number 1"]', 3, 'That is why detached daemons often have process 1 as their parent, and in containers the container''s init serves as the adopter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 4, 'Which of these signals cannot be caught by a handler?', '["SIGTERM", "SIGINT", "SIGKILL (as well as SIGSTOP)", "SIGHUP"]', 2, 'The kernel carries out KILL and STOP itself. That is why you send TERM first, so the program can clean up, and only then KILL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 5, 'Why is fork fast even for a process with gigabytes of memory?', '["Only the page tables are copied, while the pages themselves stay shared and are copied on the first write", "The kernel copies the memory in the background while the parent runs", "The child gets empty memory and loads everything again", "The memory is split between the two processes in half"]', 0, 'Copy-on-write postpones the expensive work: if the child calls exec right away, there is almost nothing to copy.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 6, 'What is a zombie process?', '["A process stuck waiting for the disk", "A parentless process that runs forever", "A process that does not react to the KILL signal", "A finished process whose parent has not yet collected the exit code with wait: an entry stays in the table"]', 3, 'A zombie uses no CPU or memory, but it holds a process number. It can be removed only if the parent calls wait or exits itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 4, 7, 'What exactly does the exec call do?', '["Creates a new process with a new number", "Replaces the program in an existing process: the process number stays, while memory and code are new", "Runs the program in a separate thread of the same process", "Copies the process together with all its memory"]', 1, 'That is why starting a program in Unix is a fork and exec pair: first a copy, then replacing its contents.');
